func newInvoiceAdjustmentSnapshot() unsafe.Pointer {
	return unsafe.Pointer(new(invoiceadjustment.InvoiceAdjustmentSnapshot))
}

func newNInvoiceAdjustmentSnapshot(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]invoiceadjustment.InvoiceAdjustmentSnapshot, n)))
}

func ptrInvoiceAdjustmentSnapshot(p unsafe.Pointer, c int32) any {
	r := (*invoiceadjustment.InvoiceAdjustmentSnapshot)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.AdjustmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.InvoiceID))
	case 5:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 6:
		return &r.Payload
	case 7:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 8:
		return &r.CreatedAt
	}
	return nil
}

func valueInvoiceAdjustmentSnapshot(p unsafe.Pointer, c int32) any {
	r := (*invoiceadjustment.InvoiceAdjustmentSnapshot)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.AdjustmentID)
	case 4:
		return string(r.InvoiceID)
	case 5:
		return string(r.Kind)
	case 6:
		if r.Payload == nil {
			return keel.EmptyJSONObject
		}
		return r.Payload
	case 7:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 8:
		return r.CreatedAt
	}
	return nil
}

